"""Run-time helpers for the user interfaces generated by frm2qt.py (PySide6).

They reproduce VB6 peculiarities Qt does not know directly: control arrays, the PictureBox,
mouse events with VB6 parameters (button, shift, x, y), key codes, drag & drop of files.
Coordinates in events are pixels (VB6 delivered twips).
"""
from __future__ import annotations

from PySide6 import QtCore, QtGui, QtWidgets


class ControlArray(dict):
    """VB6 control array: arr[index] returns the element; iteration over the elements in index order."""

    def __iter__(self):
        return iter(self[k] for k in sorted(dict.keys(self)))

    @property
    def count(self) -> int:
        return len(self)

    def indexes(self):
        return sorted(dict.keys(self))


class PictureBox(QtWidgets.QFrame):
    """Replacement for VB.PictureBox: area with a 3D frame and an optional picture; own drawing via paint_hook."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFrameShape(QtWidgets.QFrame.Shape.Panel)
        self.setFrameShadow(QtWidgets.QFrame.Shadow.Sunken)
        self.setAutoFillBackground(True)
        self.pixmap = None
        self.paint_hook = None          # optional: function(painter, rect), draws the content

    def set_picture(self, pixmap) -> None:
        self.pixmap = pixmap
        self.update()

    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QtGui.QPainter(self)
        if self.pixmap is not None:
            painter.drawPixmap(self.contentsRect(), self.pixmap)
        if self.paint_hook:
            self.paint_hook(painter, self.contentsRect())
        painter.end()


class Container(QtWidgets.QFrame):
    """Frame without border and title (VB.Frame with BorderStyle = 0)."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)


class GroupFrame(QtWidgets.QWidget):
    """Replacement for VB.Frame with border and title.

        As in VB6 the border line lies at half the height of the font, the title sits on it at the left, and the
        coordinates of the children count from the top left corner of the control. Depending on the style QGroupBox places
        the title inside the frame and would cover the children.
    """

    def __init__(self, parent=None):
        super().__init__(parent)
        self._title = ""

    def setTitle(self, text: str) -> None:
        self._title = text
        self.update()

    def title(self) -> str:
        return self._title

    def paintEvent(self, event):
        painter = QtGui.QPainter(self)
        palette = self.palette()
        role = QtGui.QPalette.ColorRole
        fm = self.fontMetrics()
        top = fm.height() // 2
        right, bottom = self.width() - 2, self.height() - 2
        text = self._title.replace("&&", "\0").replace("&", "").replace("\0", "&")
        gap = (6, 9 + fm.horizontalAdvance(text) + 3) if text else None     # gap in the top edge for the title

        def top_line(y, x0, x1):
            """Top edge; behind the title it stays interrupted. Nothing is painted over, not even neighbouring
                        controls that protrude one pixel into this control."""
            segments = [(x0, x1)] if gap is None else [(x0, min(x1, gap[0] - 1)), (max(x0, gap[1]), x1)]
            for a, b in segments:
                if a <= b:
                    painter.drawLine(a, y, b, y)

        painter.setPen(palette.color(role.Mid))                  # engraved frame: dark and light line
        top_line(top, 0, right)
        painter.drawLine(0, top, 0, bottom)
        painter.drawLine(0, bottom, right, bottom)
        painter.drawLine(right, top, right, bottom)
        painter.setPen(palette.color(role.Light))
        top_line(top + 1, 1, right + 1)
        painter.drawLine(1, top + 1, 1, bottom + 1)
        painter.drawLine(1, bottom + 1, right + 1, bottom + 1)
        painter.drawLine(right + 1, top + 1, right + 1, bottom + 1)
        if text:
            painter.setPen(palette.color(role.WindowText))
            painter.drawText(9, fm.ascent(), text)
        painter.end()


class ListView(QtWidgets.QTreeWidget):
    """MSComctlLib.ListView in the "Report" view: rows with text columns (the data lies in the application)."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setRootIsDecorated(False)
        self.setUniformRowHeights(True)

    def set_columns(self, widths: dict, stretch_column=None) -> None:
        """Column widths in pixels; 0 hides a column (like width 0 in VB6). `stretch_column` fills the rest.

                The header may have the minimum width 0, otherwise Qt would widen every column to at least about 20 pixels,
                and the last column would no longer be stretched automatically to the remaining width.
        """
        header = self.header()
        header.setStretchLastSection(False)
        header.setMinimumSectionSize(0)
        for col, width in widths.items():
            self.setColumnWidth(col, width)
        if stretch_column is not None:
            header.setSectionResizeMode(stretch_column, QtWidgets.QHeaderView.ResizeMode.Stretch)

    def set_rows(self, rows) -> None:
        self.clear()
        for row in rows:
            self.addTopLevelItem(QtWidgets.QTreeWidgetItem([str(x) for x in row]))

    def row_count(self) -> int:
        return self.topLevelItemCount()

    def current_row(self) -> int:
        """Index of the selected row (0-based), -1 = none."""
        item = self.currentItem()
        return -1 if item is None else self.indexOfTopLevelItem(item)

    def select_row(self, i: int) -> None:
        item = self.topLevelItem(i)
        if item is not None:
            self.setCurrentItem(item)
            self.scrollToItem(item)

    def set_row(self, i: int, values) -> None:
        item = self.topLevelItem(i)
        for col, value in enumerate(values):
            item.setText(col, str(value))

    def set_bold(self, i: int, col: int, bold: bool) -> None:
        item = self.topLevelItem(i)
        if item is not None:
            font = item.font(col)
            font.setBold(bold)
            item.setFont(col, font)


# ----------------------------------------------------------------------------- Font, window
_DEFAULT_FAMILIES = {"ms sans serif", "ms shell dlg", "ms shell dlg 2", "microsoft sans serif", "tahoma", "arial"}
# Fonts with the metrics of Arial; MS Sans Serif is similarly narrow. DejaVu Sans and others are clearly wider
# and cut off the fixed-size VB6 captions.
_PREFERRED = ("Liberation Sans", "Arimo", "Arial", "Nimbus Sans", "Helvetica")
_family_cache = []


def windows_font_family() -> str:
    """Suitable replacement font for the Windows standard fonts ('' = keep the system font)."""
    if not _family_cache:
        have = set(QtGui.QFontDatabase.families())
        _family_cache.append(next((f for f in _PREFERRED if f in have), ""))
    return _family_cache[0]


def make_font(name: str, size: float, weight: int = 400, italic: int = 0, underline: int = 0, strike: int = 0):
    """VB6 font -> QFont. The Windows standard fonts are replaced by a font of similar width
        (Liberation Sans or similar), otherwise by the system font; the size stays."""
    font = QtGui.QFont(QtWidgets.QApplication.font())
    if name.lower() in _DEFAULT_FAMILIES:
        family = windows_font_family()
        if family:
            font.setFamily(family)
    else:
        font.setFamily(name)
    font.setPointSizeF(size)
    font.setBold(weight >= 700)
    font.setItalic(bool(italic))
    font.setUnderline(bool(underline))
    font.setStrikeOut(bool(strike))
    return font


def center_on_screen(widget) -> None:
    geometry = widget.screen().availableGeometry()
    frame = widget.frameGeometry()
    frame.moveCenter(geometry.center())
    widget.move(frame.topLeft())


def set_cancel(window, button) -> None:
    """VB6: Cancel = True. Esc triggers the button."""
    shortcut = QtGui.QShortcut(QtGui.QKeySequence("Esc"), window)
    shortcut.activated.connect(button.click)


# ----------------------------------------------------------------------------- Events in VB6 style
_KEYS = {0x01000000: 27, 0x01000001: 9, 0x01000003: 8, 0x01000004: 13, 0x01000005: 13, 0x01000006: 45,
         0x01000007: 46, 0x01000010: 36, 0x01000011: 35, 0x01000012: 37, 0x01000013: 38, 0x01000014: 39,
         0x01000015: 40, 0x01000016: 33, 0x01000017: 34}


def vb_keycode(qt_key: int) -> int:
    """Qt key code -> VB6 KeyCode (letters/digits are the same, F1..F12 = 112..123)."""
    if qt_key in _KEYS:
        return _KEYS[qt_key]
    if 0x01000030 <= qt_key <= 0x0100003B:
        return 112 + qt_key - 0x01000030
    return qt_key if qt_key < 256 else 0


def vb_shift(modifiers) -> int:
    """Modifier keys: 1 = Shift, 2 = Ctrl, 4 = Alt (as in VB6)."""
    m = QtCore.Qt.KeyboardModifier
    return (1 if modifiers & m.ShiftModifier else 0) | (2 if modifiers & m.ControlModifier else 0) | \
           (4 if modifiers & m.AltModifier else 0)


def vb_button(buttons) -> int:
    """Mouse buttons: 1 = left, 2 = right, 4 = middle (as in VB6)."""
    b = QtCore.Qt.MouseButton
    return (1 if buttons & b.LeftButton else 0) | (2 if buttons & b.RightButton else 0) | \
           (4 if buttons & b.MiddleButton else 0)


class _Filter(QtCore.QObject):
    """One event filter per control; passes events on to functions in VB6 style."""

    def __init__(self, widget):
        super().__init__(widget)
        self.widget = widget
        self.handlers = {}
        widget.installEventFilter(self)
        if hasattr(widget, "viewport"):
            widget.viewport().installEventFilter(self)

    def eventFilter(self, obj, ev):
        t = ev.type()
        E = QtCore.QEvent.Type
        h = self.handlers
        try:
            if t == E.MouseButtonPress and "down" in h:
                p = ev.position()
                h["down"](vb_button(ev.button()), vb_shift(ev.modifiers()), int(p.x()), int(p.y()))
            elif t == E.MouseMove and "move" in h:
                p = ev.position()
                h["move"](vb_button(ev.buttons()), vb_shift(ev.modifiers()), int(p.x()), int(p.y()))
            elif t == E.MouseButtonRelease:
                p = ev.position()
                if "up" in h:
                    h["up"](vb_button(ev.button()), vb_shift(ev.modifiers()), int(p.x()), int(p.y()))
                if "click" in h and ev.button() == QtCore.Qt.MouseButton.LeftButton and self.widget.rect().contains(p.toPoint()):
                    h["click"]()
            elif t == E.MouseButtonDblClick and "dblclick" in h:
                h["dblclick"]()
            elif t == E.KeyPress and "keydown" in h:
                h["keydown"](vb_keycode(ev.key()), vb_shift(ev.modifiers()))
            elif t == E.KeyRelease and "keyup" in h:
                h["keyup"](vb_keycode(ev.key()), vb_shift(ev.modifiers()))
            elif t == E.DragEnter and "drop" in h:
                if ev.mimeData().hasUrls():
                    ev.acceptProposedAction()
                    return True
            elif t == E.DragMove and "drop" in h:
                ev.acceptProposedAction()
                return True
            elif t == E.Drop and "drop" in h:
                files = [u.toLocalFile() for u in ev.mimeData().urls() if u.isLocalFile()]
                h["drop"](files)
                ev.acceptProposedAction()
                return True
        except Exception:                                  # errors in the handler must not paralyse the user interface
            import traceback
            traceback.print_exc()
        return False


def _filter(widget) -> _Filter:
    f = getattr(widget, "_vb_filter", None)
    if f is None:
        f = widget._vb_filter = _Filter(widget)
    return f


def on_mouse(widget, down=None, move=None, up=None) -> None:
    """Handler(button, shift, x, y); x and y in pixels relative to the control."""
    f = _filter(widget)
    if move:
        widget.setMouseTracking(True)
    for key, fn in (("down", down), ("move", move), ("up", up)):
        if fn:
            f.handlers[key] = fn


def _shift_down() -> bool:
    """Is the Shift key down right now? (asks the window system; where that is not possible, the state of the last event)"""
    app = QtWidgets.QApplication
    query = getattr(app, "queryKeyboardModifiers", None) or app.keyboardModifiers
    return bool(query() & QtCore.Qt.KeyboardModifier.ShiftModifier)


class ShiftToolTip(QtCore.QObject):
    """Tooltip of a control that shows another text while the Shift key is held down (for buttons whose Shift + click does something
    else). The text follows the key: it is chosen when the pointer enters the control or moves over it, when the tooltip is about to
    appear, and as long as the pointer stays on the control a timer looks at the key several times a second, so pressing or releasing
    Shift also changes a tooltip that is already showing. Only events of this control are watched, not those of the whole application."""

    POLL_MS = 100

    def __init__(self, widget, normal: str, with_shift: str, shift_down=None):
        super().__init__(widget)
        self.widget, self.normal, self.with_shift = widget, normal, with_shift
        self._shift_down = shift_down or _shift_down
        self.shift = False
        self.timer = QtCore.QTimer(self)
        self.timer.setInterval(self.POLL_MS)
        self.timer.timeout.connect(self.poll)
        widget.setToolTip(normal)
        widget.installEventFilter(self)

    def poll(self) -> None:
        self.set_shift(self._shift_down())

    def set_shift(self, shift: bool) -> None:
        if shift == self.shift:
            return
        self.shift = shift
        text = self.with_shift if shift else self.normal
        self.widget.setToolTip(text)
        if QtWidgets.QToolTip.isVisible() and self.widget.underMouse():
            QtWidgets.QToolTip.showText(QtGui.QCursor.pos(), text, self.widget)

    def eventFilter(self, obj, ev):
        if obj is not self.widget:
            return False
        t, E = ev.type(), QtCore.QEvent.Type
        if t == E.Enter:
            self.poll()
            self.timer.start()                                  # watches the key as long as the pointer is on the control
        elif t == E.Leave:
            self.timer.stop()
        elif t in (E.ToolTip, E.MouseMove):
            self.poll()
        return False


def on_click(widget, fn) -> None:
    _filter(widget).handlers["click"] = fn


def on_double_click(widget, fn) -> None:
    _filter(widget).handlers["dblclick"] = fn


def on_key(widget, down=None, up=None) -> None:
    """Handler(keycode, shift) with VB6 key codes."""
    f = _filter(widget)
    if down:
        f.handlers["keydown"] = down
    if up:
        f.handlers["keyup"] = up


def on_drop(widget, fn) -> None:
    """Handler(file list): files that are dragged onto the control (OLEDragDrop)."""
    widget.setAcceptDrops(True)
    if hasattr(widget, "viewport"):
        widget.viewport().setAcceptDrops(True)
    _filter(widget).handlers["drop"] = fn


def fit_labels(root, margin: int = 6) -> None:
    """Widens left-aligned captions whose text does not fit, as far as there is room to the right of them.

        Linux fonts are somewhat wider than MS Sans Serif; the fixed-size VB6 captions would otherwise be cut off
        (e.g. at the colon). Neighbours in the same row are not covered.
    """
    for label in root.findChildren(QtWidgets.QLabel):
        text = label.text()
        parent = label.parentWidget()
        if not text or parent is None or label.wordWrap():
            continue
        if not (label.alignment() & QtCore.Qt.AlignmentFlag.AlignLeft):
            continue
        need = label.fontMetrics().horizontalAdvance(text.replace("&", "")) + 2 * label.frameWidth() + margin
        g = label.geometry()
        if need <= g.width():
            continue
        limit = None
        for sib in parent.children():
            if sib is label or not isinstance(sib, QtWidgets.QWidget) or sib.isHidden():
                continue
            r = sib.geometry()
            if r.left() >= g.left() + g.width() and r.top() < g.top() + g.height() and r.top() + r.height() > g.top():
                limit = r.left() if limit is None else min(limit, r.left())
        width = need if limit is None else min(need, limit - 2 - g.left())
        if width > g.width():
            label.setGeometry(g.left(), g.top(), width, g.height())


# ----------------------------------------------------------------------------- Appearance
def apply_light_theme(app) -> None:
    """Light appearance independent of the desktop theme (Fusion style with fixed Windows-like colours)."""
    hints = app.styleHints()
    if hasattr(hints, "setColorScheme"):                     # ab Qt 6.8
        hints.setColorScheme(QtCore.Qt.ColorScheme.Light)
    app.setStyle("Fusion")
    P = QtGui.QPalette
    R, G, C = P.ColorRole, P.ColorGroup, QtGui.QColor
    palette = P()
    for role, color in ((R.Window, C(240, 240, 240)), (R.WindowText, C(0, 0, 0)), (R.Base, C(255, 255, 255)),
                        (R.AlternateBase, C(245, 245, 245)), (R.ToolTipBase, C(255, 255, 225)),
                        (R.ToolTipText, C(0, 0, 0)), (R.Text, C(0, 0, 0)), (R.Button, C(240, 240, 240)),
                        (R.ButtonText, C(0, 0, 0)), (R.BrightText, C(255, 0, 0)), (R.Link, C(0, 0, 255)),
                        (R.Highlight, C(49, 106, 197)), (R.HighlightedText, C(255, 255, 255)),
                        (R.PlaceholderText, C(128, 128, 128)), (R.Light, C(255, 255, 255)),
                        (R.Midlight, C(227, 227, 227)), (R.Mid, C(160, 160, 160)), (R.Dark, C(105, 105, 105))):
        palette.setColor(role, color)
    for role in (R.WindowText, R.Text, R.ButtonText):
        palette.setColor(G.Disabled, role, C(128, 128, 128))
    app.setPalette(palette)


def english_shortcuts(owner) -> None:
    """The menu entries show their shortcut in the language of the system ("Strg+S" on a German one), because Qt translates the names of the keys. The menus of the
    program are English, so the text of the shortcut is written into the entry by hand ("Save as...<tab>Ctrl+S"): Qt adds its own text only if the text of the entry has no
    tab (the shortcut itself works as before). All actions that the window holds as attributes (the form makes them as self.mnuXxx) are done."""
    for action in [a for a in vars(owner).values() if isinstance(a, QtGui.QAction)]:
        keys = action.shortcut()
        if keys.isEmpty():
            continue
        action.setText(action.text().split("\t")[0] + "\t" + keys.toString(QtGui.QKeySequence.SequenceFormat.PortableText))
